26	function titleFromSlug(slug: string): string {
27	  const base = slug.split('/').pop() ?? slug;
28	  return base
29	    .split(/[-_]/)
30	    .filter((word) => word.length > 0)
31	    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
32	    .join(' ');
33	}
