48	/** Reads markdown content from contentDir, converts it to HTML, and writes the site to outputDir. */
49	export function build(options: BuildOptions): BuildResult {
50	  const { contentDir, outputDir } = options;
51	  const siteTitle = options.siteTitle ?? 'My Site';
52	
53	  if (!fs.existsSync(contentDir) || !fs.statSync(contentDir).isDirectory()) {
54	    throw new Error(`Content directory not found: ${contentDir}`);
55	  }
56	
57	  const markdownFiles = findMarkdownFiles(contentDir).sort();
58	
59	  const pages: Page[] = markdownFiles.map((filePath) => {
60	    const raw = fs.readFileSync(filePath, 'utf-8');
61	    const slug = toSlug(contentDir, filePath);
62	    const { frontmatter, contentHtml } = parseMarkdown(raw, titleFromSlug(slug));
63	    return { slug, frontmatter, contentHtml, sourcePath: filePath };
64	  });
65	
66	  pages.sort(comparePages);
67	
68	  fs.rmSync(outputDir, { recursive: true, force: true });
69	  fs.mkdirSync(outputDir, { recursive: true });
70	
71	  const outputFiles: string[] = [];
72	
73	  for (const page of pages) {
74	    const outputPath = path.join(outputDir, `${page.slug}.html`);
75	    fs.mkdirSync(path.dirname(outputPath), { recursive: true });
76	    fs.writeFileSync(outputPath, renderPageHtml(page), 'utf-8');
77	    outputFiles.push(outputPath);
78	  }
79	
80	  const indexPath = path.join(outputDir, 'index.html');
81	  fs.writeFileSync(indexPath, renderIndexHtml(pages, siteTitle), 'utf-8');
82	  outputFiles.push(indexPath);
83	
84	  const stylesheetPath = path.join(outputDir, 'style.css');
85	  fs.writeFileSync(stylesheetPath, DEFAULT_STYLESHEET, 'utf-8');
86	  outputFiles.push(stylesheetPath);
87	
88	  return { pages, outputFiles };
89	}
