3	export function escapeHtml(value: string): string {
4	  return value
5	    .replace(/&/g, '&amp;')
6	    .replace(/</g, '&lt;')
7	    .replace(/>/g, '&gt;')
8	    .replace(/"/g, '&quot;')
9	    .replace(/'/g, '&#39;');
10	}
11	
12	function renderMeta(page: Page): string {
13	  const parts: string[] = [];
14	  if (page.frontmatter.date) {
15	    parts.push(`<time datetime="${escapeHtml(page.frontmatter.date)}">${escapeHtml(page.frontmatter.date)}</time>`);
16	  }
17	  if (page.frontmatter.tags.length > 0) {
18	    const tags = page.frontmatter.tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ');
19	    parts.push(`<span class="tags">${tags}</span>`);
20	  }
21	  return parts.length > 0 ? `<p class="meta">${parts.join(' &middot; ')}</p>` : '';
22	}
