24	export function renderPageHtml(page: Page): string {
25	  const title = escapeHtml(page.frontmatter.title);
26	  return `<!DOCTYPE html>
27	<html lang="en">
28	<head>
29	  <meta charset="UTF-8">
30	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
31	  <title>${title}</title>
32	  <link rel="stylesheet" href="${'../'.repeat(page.slug.split('/').length - 1)}style.css">
33	</head>
34	<body>
35	  <header>
36	    <a href="${'../'.repeat(page.slug.split('/').length - 1)}index.html">&larr; Back to index</a>
37	  </header>
38	  <main>
39	    <article>
40	      <h1>${title}</h1>
41	      ${renderMeta(page)}
42	      ${page.contentHtml}
43	    </article>
44	  </main>
45	</body>
46	</html>
47	`;
48	}
