50	export function renderIndexHtml(pages: Page[], siteTitle: string): string {
51	  const items = pages
52	    .map((page) => {
53	      const title = escapeHtml(page.frontmatter.title);
54	      const href = `${page.slug}.html`;
55	      return `      <li>
56	        <a href="${escapeHtml(href)}">${title}</a>
57	        ${renderMeta(page)}
58	      </li>`;
59	    })
60	    .join('\n');
61	
62	  return `<!DOCTYPE html>
63	<html lang="en">
64	<head>
65	  <meta charset="UTF-8">
66	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
67	  <title>${escapeHtml(siteTitle)}</title>
68	  <link rel="stylesheet" href="style.css">
69	</head>
70	<body>
71	  <header>
72	    <h1>${escapeHtml(siteTitle)}</h1>
73	  </header>
74	  <main>
75	    <ul class="page-list">
76	${items}
77	    </ul>
78	  </main>
79	</body>
80	</html>
81	`;
