7	function normalizeDate(value: unknown): string | undefined {
8	  if (value instanceof Date) {
9	    return value.toISOString().slice(0, 10);
10	  }
11	  if (typeof value === 'string' && value.trim().length > 0) {
12	    return value.trim();
13	  }
14	  return undefined;
15	}
16	
17	function normalizeTags(value: unknown): string[] {
18	  if (Array.isArray(value)) {
19	    return value.map((tag) => String(tag).trim()).filter((tag) => tag.length > 0);
20	  }
21	  if (typeof value === 'string' && value.trim().length > 0) {
22	    return value
23	      .split(',')
24	      .map((tag) => tag.trim())
25	      .filter((tag) => tag.length > 0);
26	  }
27	  return [];
28	}
