35	/** Parses raw markdown (with optional YAML frontmatter) into HTML and structured frontmatter. */
36	export function parseMarkdown(raw: string, fallbackTitle: string): ParsedMarkdown {
37	  const { data, content } = matter(raw);
38	
39	  const frontmatter: PageFrontmatter = {
40	    title: typeof data.title === 'string' && data.title.trim().length > 0 ? data.title.trim() : fallbackTitle,
41	    date: normalizeDate(data.date),
42	    tags: normalizeTags(data.tags),
43	  };
44	
45	  const contentHtml = marked.parse(content, { async: false }) as string;
46	
47	  return { frontmatter, contentHtml };
48	}
