12	export function parseArgs(argv: string[]): CliArgs {
13	  const [command = 'build', ...rest] = argv;
14	  let contentDir = DEFAULT_CONTENT_DIR;
15	  let outputDir = DEFAULT_OUTPUT_DIR;
16	
17	  for (let i = 0; i < rest.length; i++) {
18	    const arg = rest[i];
19	    if (arg === '--content') {
20	      const value = rest[i + 1];
21	      if (!value) throw new Error('--content requires a directory argument');
22	      contentDir = value;
23	      i++;
24	    } else if (arg === '--output') {
25	      const value = rest[i + 1];
26	      if (!value) throw new Error('--output requires a directory argument');
27	      outputDir = value;
28	      i++;
29	    } else {
30	      throw new Error(`Unknown argument: ${arg}`);
31	    }
32	  }
33	
34	  return { command, contentDir, outputDir };
35	}
